#[inline]
fn destack_ipc_unix_receive_replay(
    context: &RuntimeCallContext,
    world: RuntimeWorld,
    out: *mut UnixReceiveAncillary,
    socket: resource::SocketHandle,
    maxhandles: u32,
) -> RuntimeResult<()> {
    let _ = (&socket, &maxhandles);

    context.replay().run_binding_with_payload_policy(
        IPC_UNIX_RECEIVE,
        context.replay_payload_for(IPC_UNIX_RECEIVE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_ipc_unix_receive(context, out, socket, maxhandles)
            },
            RuntimeWorld::Simulated => unsafe {
                platform_simulated_native::destack_ipc_unix_receive(
                    context, out, socket, maxhandles,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_bytes = result_value.bytes;
                let result_recorded_handles_raw = unsafe { result_value.handles.as_slice()? };
                let mut result_recorded_handles =
                    Vec::with_capacity(result_recorded_handles_raw.len());
                for result_recorded_handles_item_value in result_recorded_handles_raw {
                    let result_recorded_handles_item = *result_recorded_handles_item_value;
                    let result_recorded_handles_item_recorded = result_recorded_handles_item;
                    result_recorded_handles.push(result_recorded_handles_item_recorded);
                }
                let result_recorded_credentials_pid = result_value.credentials.pid;
                let result_recorded_credentials_uid = result_value.credentials.uid;
                let result_recorded_credentials_gid = result_value.credentials.gid;
                let result_recorded_credentials = UnixPeerCredentials {
                    pid: result_recorded_credentials_pid,
                    uid: result_recorded_credentials_uid,
                    gid: result_recorded_credentials_gid,
                };
                let result_recorded = UnixReceiveAncillaryReplayRecord {
                    bytes: result_recorded_bytes,
                    handles: result_recorded_handles,
                    credentials: result_recorded_credentials,
                };
                let payload = IpcUnixReceiveReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    IpcUnixReceiveReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_bytes = value.bytes;
                    let mut value_native_handles_values = Vec::with_capacity(value.handles.len());
                    for value_native_handles_item in value.handles {
                        let value_native_handles_item_native = value_native_handles_item;
                        value_native_handles_values.push(value_native_handles_item_native);
                    }
                    let value_native_handles = context.store_array(value_native_handles_values);
                    let value_native_credentials_pid = value.credentials.pid;
                    let value_native_credentials_uid = value.credentials.uid;
                    let value_native_credentials_gid = value.credentials.gid;
                    let value_native_credentials = UnixPeerCredentials {
                        pid: value_native_credentials_pid,
                        uid: value_native_credentials_uid,
                        gid: value_native_credentials_gid,
                    };
                    let value_native = UnixReceiveAncillary {
                        bytes: value_native_bytes,
                        handles: value_native_handles,
                        credentials: value_native_credentials,
                    };
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

